-- V26__au_localities.sql
-- Reference table of Australian suburbs/localities with coordinates, used to
-- compute candidate-to-search-location proximity (Location Intelligence radius
-- slider on the Smart Talent Lens candidates page). Sourced from GeoNames.org
-- (AU postal code dataset, CC BY 4.0), ~18.5k entries covering every Australian
-- state/territory. Suburb-level centroid coordinates, not exact street addresses.

CREATE TABLE IF NOT EXISTS au_localities (
    id BIGSERIAL PRIMARY KEY,
    suburb TEXT NOT NULL,
    state_name TEXT NOT NULL,
    state_code TEXT NOT NULL,
    postcode TEXT,
    latitude NUMERIC(9,6) NOT NULL,
    longitude NUMERIC(9,6) NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_au_localities_suburb_state
    ON au_localities (lower(suburb), state_code);







































